/** Igual que mergeActividadesConCustom del Calendario: base + cambios + propias, sin ocultas */
function actividades(custom: any[]): Act[] {
  const over: Record<number, any> = {};
  (custom ?? []).filter(r => r.base_id != null).forEach(r => { over[r.base_id] = r; });
  const base: Act[] = BASE.filter(([id]) => !over[id]?.eliminado).map(([id, cat, act, f]) => {
    const o = over[id];
    return { ref: `base:${id}`, categoria: o?.categoria ?? cat, actividad: o?.actividad ?? act, frecuenciaDias: o?.frecuencia_dias ?? f };
  });
  const propias: Act[] = (custom ?? []).filter(r => r.base_id == null && !r.eliminado)
    .map(r => ({ ref: `custom:${r.id}`, categoria: r.categoria, actividad: r.actividad, frecuenciaDias: r.frecuencia_dias }));
  return [...base, ...propias];
}

const iso = (t: number) => new Date(t).toISOString().slice(0, 10);
/** Fechas programadas entre dos días (YYYY-MM-DD): domingo se recorre a lunes; las diarias no corren en domingo */
function fechas(a: Act, desde: string, hasta: string): string[] {
  const out: string[] = [];
  const ini = Date.parse(desde + 'T00:00:00Z'), fin = Date.parse(hasta + 'T00:00:00Z');
  for (let t = FECHA_BASE; t <= fin; t += a.frecuenciaDias * DIA) {
    const domingo = new Date(t).getUTCDay() === 0;
    if (domingo && a.frecuenciaDias === 1) continue;
    const m = domingo ? t + DIA : t;
    if (m >= ini && m <= fin) out.push(iso(m));
  }
  return out;
}

// ─── Cálculo por colegio ─────────────────────────────────────────────────────
interface Resultado {
  colegio: string; nombre: string; año: number; mes: number;
  anual: { prog: number; hechas: number; pct: number; desde: string; hasta: string };
  mensual: { prog: number; hechas: number; pct: number };
  categorias: { categoria: string; prog: number; hechas: number }[];
  pendientes: { actividad: string; categoria: string; veces: number }[];
}
const pct = (h: number, p: number) => (p > 0 ? Math.min(100, Math.round((h / p) * 100)) : 0);

function calcular(colegio: string, nombre: string, acts: Act[], comp: { actividad_ref: string; fecha_programada: string }[], año: number, mes: number): Resultado {
  const finMes = iso(Date.UTC(año, mes + 1, 0));
  const iniMes = iso(Date.UTC(año, mes, 1));
  const desde = año === 2026 ? INICIO_REGISTRO : `${año}-01-01`;
  const hechasSet = new Set(comp.map(c => `${c.actividad_ref}|${c.fecha_programada}`));
  let progA = 0;
  const cats = new Map<string, { prog: number; hechas: number }>();
  const pend: Resultado['pendientes'] = [];
  let progM = 0, hechasM = 0;
  for (const a of acts) {
    progA += fechas(a, desde, finMes).length;
    const delMes = fechas(a, iniMes, finMes);
    if (!delMes.length) continue;
    const hechas = delMes.filter(f => hechasSet.has(`${a.ref}|${f}`)).length;
    progM += delMes.length; hechasM += hechas;
    const c = cats.get(a.categoria) ?? { prog: 0, hechas: 0 };
    c.prog += delMes.length; c.hechas += hechas; cats.set(a.categoria, c);
    if (hechas < delMes.length) pend.push({ actividad: a.actividad, categoria: a.categoria, veces: delMes.length - hechas });
  }
  const hechasA = comp.filter(c => c.fecha_programada >= desde && c.fecha_programada <= finMes).length;
  return {
    colegio, nombre, año, mes,
    anual: { prog: progA, hechas: Math.min(hechasA, progA), pct: pct(hechasA, progA), desde, hasta: finMes },
    mensual: { prog: progM, hechas: hechasM, pct: pct(hechasM, progM) },
    categorias: [...cats.entries()].map(([categoria, v]) => ({ categoria, ...v })),
    pendientes: pend.sort((a, b) => b.veces - a.veces),
  };
}

type Nivel = 'atencion' | 'bien' | 'excelente';
const nivelDe = (p: number): Nivel => (p >= 100 ? 'excelente' : p >= UMBRAL_BIEN ? 'bien' : 'atencion');

// ─── PDF (mismo diseño "Ejecutivo" de la Solicitud de Proyecto y el Ticket MAS) ─
const NAVY = rgb(31 / 255, 78 / 255, 121 / 255), NAVY_MID = rgb(36 / 255, 89 / 255, 138 / 255), BLUE = rgb(91 / 255, 135 / 255, 181 / 255);
const ORANGE = rgb(232 / 255, 119 / 255, 34 / 255), BLANCO = rgb(1, 1, 1);
const INK = rgb(0.12, 0.16, 0.23), MUTED = rgb(0.39, 0.45, 0.55), LINE = rgb(0.886, 0.91, 0.94), SUAVE = rgb(0.933, 0.949, 0.969), GRIS = rgb(0.945, 0.961, 0.976);
const ROJO = rgb(0.863, 0.149, 0.149), AMBAR = rgb(0.851, 0.467, 0.024), VERDE = rgb(0.086, 0.639, 0.29);
const colorNivel = (n: Nivel) => (n === 'excelente' ? VERDE : n === 'bien' ? AMBAR : ROJO);
const etiquetaNivel = (n: Nivel) => (n === 'excelente' ? 'Excelente' : n === 'bien' ? 'Va bien' : 'Requiere atención');
const fechaLarga = (d: string) => { const [y, m, dd] = d.split('-').map(Number); return `${dd} de ${MESES[m - 1]} de ${y}`; };
const fechaCorta = (d: string) => { const [y, m, dd] = d.split('-').map(Number); return `${dd} ${MESES[m - 1].slice(0, 3)} ${y}`; };
const b64 = (s: string) => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const Mayus = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

function envolver(texto: string, font: PDFFont, size: number, ancho: number): string[] {
  const lineas: string[] = []; let l = '';
  for (const p of texto.split(/\s+/)) {
    const prueba = l ? `${l} ${p}` : p;
    if (font.widthOfTextAtSize(prueba, size) > ancho && l) { lineas.push(l); l = p; } else l = prueba;
  }
  if (l) lineas.push(l);
  return lineas;
}
/** Rectángulo redondeado (x, y = esquina inferior izquierda) */
function rr(page: PDFPage, x: number, y: number, w: number, h: number, r: number, op: { color?: any; borderColor?: any; borderWidth?: number; borderDashArray?: number[] }) {
  const p = `M ${r} 0 H ${w - r} Q ${w} 0 ${w} ${r} V ${h - r} Q ${w} ${h} ${w - r} ${h} H ${r} Q 0 ${h} 0 ${h - r} V ${r} Q 0 0 ${r} 0 Z`;
  page.drawSvgPath(p, { x, y: y + h, ...op });
}

interface Ficha { director?: string; administrador?: string; car?: string }

async function construirPdf(r: Resultado, folio: string, emision: string, ficha: Ficha = {}): Promise<Uint8Array> {
  const pdf = await PDFDocument.create();
  pdf.setTitle(`${folio} · Reporte mensual de mantenimiento`); pdf.setAuthor('Sistema RCMA'); pdf.setCreator('Sistema RCMA');
  const R = await pdf.embedFont(StandardFonts.Helvetica), B = await pdf.embedFont(StandardFonts.HelveticaBold), I = await pdf.embedFont(StandardFonts.HelveticaOblique);
  const logo: PDFImage = await pdf.embedPng(b64(LOGO_B64));
  const W = 612, H = 792, M = 40, AN = W - 2 * M;
  const nivel = nivelDe(r.anual.pct), cN = colorNivel(nivel);
  const mesTxt = `${Mayus(MESES[r.mes])} ${r.año}`;
  let page: PDFPage = pdf.addPage([W, H]);
  let y = 0;

  // Franja azul con corte naranja + logo en tarjeta blanca
  const franja = (compacta = false) => {
    const h = compacta ? 54 : 92, top = H, base = H - h, s = h * 0.36;
    page.drawRectangle({ x: 0, y: base, width: W, height: h, color: NAVY });
    page.drawSvgPath(`M ${W * 0.62 + s} 0 L ${W * 0.76 + s} 0 L ${W * 0.76 - s} ${h} L ${W * 0.62 - s} ${h} Z`, { x: 0, y: top, color: NAVY_MID });
    page.drawSvgPath(`M ${W * 0.76 + s} 0 L ${W} 0 L ${W} ${h} L ${W * 0.76 - s} ${h} Z`, { x: 0, y: top, color: ORANGE });
    const lh = compacta ? 26 : 34, lw = lh * logo.width / logo.height;
    rr(page, W - M - lw - 16, base + (h - lh - 12) / 2 + (compacta ? 0 : 4), lw + 16, lh + 12, 7, { color: BLANCO });
    page.drawImage(logo, { x: W - M - lw - 8, y: base + (h - lh) / 2 + (compacta ? 0 : 4), width: lw, height: lh });
    if (compacta) {
      page.drawText('REPORTE MENSUAL DE MANTENIMIENTO', { x: M, y: base + 30, size: 12, font: B, color: BLANCO });
      page.drawText(`${folio}  ·  ${r.nombre}`, { x: M, y: base + 16, size: 8.5, font: R, color: rgb(0.85, 0.89, 0.94) });
      y = base - 18;
    } else {
      page.drawText('RED DE COLEGIOS MANO AMIGA', { x: M, y: top - 26, size: 7.5, font: B, color: rgb(0.8, 0.85, 0.92), characterSpacing: 1.6 } as any);
      page.drawText('REPORTE MENSUAL DE MANTENIMIENTO', { x: M, y: top - 48, size: 17, font: B, color: BLANCO });
      page.drawText(`Cronograma de Mantenimiento · ${mesTxt}`, { x: M, y: top - 64, size: 9, font: R, color: rgb(0.85, 0.89, 0.94) });
      y = base;
    }
  };
  // Pie azul
  const pie = () => {
    page.drawRectangle({ x: 0, y: 0, width: W, height: 26, color: NAVY });
    page.drawText('Colegios Mano Amiga — Juntos Transformando Vidas.', { x: M, y: 10, size: 8, font: I, color: BLANCO });
  };
  const nuevaPagina = () => { pie(); page = pdf.addPage([W, H]); franja(true); };
  const espacio = (alto: number) => { if (y - alto < 34) nuevaPagina(); };

  // Tarjeta con título (gris con barra naranja) — devuelve la y de su contenido
  const tituloTarjeta = (t: string) => {
    espacio(44);
    rr(page, M, y - 20, AN, 20, 6, { color: GRIS });
    page.drawRectangle({ x: M, y: y - 20, width: 4, height: 20, color: ORANGE });
    page.drawText(t.toUpperCase(), { x: M + 14, y: y - 13.5, size: 9, font: B, color: NAVY });
    y -= 20;
  };
  const cerrarTarjeta = (desde: number) => {
    page.drawLine({ start: { x: M, y: desde }, end: { x: M, y }, thickness: 0.8, color: LINE });
    page.drawLine({ start: { x: M + AN, y: desde }, end: { x: M + AN, y }, thickness: 0.8, color: LINE });
    page.drawLine({ start: { x: M, y }, end: { x: M + AN, y }, thickness: 0.8, color: LINE });
    y -= 9;
  };

  franja();

  // KPIs sobre la franja
  const kpis: [string, string, any, boolean?][] = [
    ['Folio', folio, ROJO], ['Colegio', r.colegio, NAVY], ['Mes reportado', mesTxt, NAVY], ['Avance acumulado', `${r.anual.pct} %`, cN, true],
  ];
  const kw = (AN - 3 * 10) / 4, ktop = y + 14, kh = 40;
  kpis.forEach(([et, v, col, pill], i) => {
    const x = M + i * (kw + 10);
    rr(page, x + 1, ktop - kh - 2, kw, kh, 7, { color: rgb(0.86, 0.88, 0.91) });  // sombra
    rr(page, x, ktop - kh, kw, kh, 7, { color: BLANCO });
    page.drawRectangle({ x: x + 4, y: ktop - 3, width: kw - 8, height: 3, color: i === 1 ? ORANGE : NAVY });
    page.drawText(et.toUpperCase(), { x: x + 10, y: ktop - 15, size: 6.5, font: B, color: MUTED });
    if (pill) {
      const tw = B.widthOfTextAtSize(v, 11);
      rr(page, x + 8, ktop - 35, tw + 14, 15, 7.5, { color: cN, borderColor: cN, borderWidth: 0 });
      page.drawText(v, { x: x + 15, y: ktop - 31, size: 11, font: B, color: BLANCO });
    } else page.drawText(v, { x: x + 10, y: ktop - 31, size: 11, font: B, color: col });
  });
  y = ktop - kh - 12;

  // Datos del reporte (cuadrícula de 3)
  tituloTarjeta('Datos del reporte');
  let ini = y;
  const datos: [string, string][] = [
    ['Colegio', r.nombre], ['Director(a)', ficha.director || '—'], ['Administrador(a)', ficha.administrador || '—'],
    ['Periodo del avance anual', `${fechaCorta(r.anual.desde)} al ${fechaCorta(r.anual.hasta)}`], ['CAR', ficha.car || '—'], ['Fecha de emisión', emision],
  ];
  const cw = AN / 3;
  datos.forEach(([k, v], i) => {
    const col = i % 3, fila = Math.floor(i / 3), x = M + col * cw, yy = ini - fila * 29;
    if (fila > 0 && col === 0) page.drawLine({ start: { x: M, y: yy }, end: { x: M + AN, y: yy }, thickness: 0.6, color: SUAVE });
    page.drawText(k.toUpperCase(), { x: x + 12, y: yy - 12, size: 6.5, font: B, color: MUTED });
    const lineas = envolver(v, B, 8.5, cw - 20);
    lineas.slice(0, 2).forEach((l, j) => page.drawText(l, { x: x + 12, y: yy - 23 - j * 9, size: 8.5, font: B, color: INK }));
  });
  y = ini - 2 * 29 - 2;
  cerrarTarjeta(ini);

  // Avance del cronograma
  tituloTarjeta('Avance del cronograma');
  ini = y;
  const bloque = (x: number, w: number, titulo: string, p: number, det: string, col: any) => {
    page.drawText(titulo.toUpperCase(), { x: x + 14, y: ini - 18, size: 7, font: B, color: MUTED });
    page.drawText(`${p} %`, { x: x + 14, y: ini - 46, size: 24, font: B, color: col });
    rr(page, x + 14, ini - 60, w - 28, 8, 4, { color: SUAVE });
    if (p > 0) rr(page, x + 14, ini - 60, Math.max(8, (w - 28) * Math.min(p, 100) / 100), 8, 4, { color: col });
    page.drawText(det, { x: x + 14, y: ini - 73, size: 8, font: R, color: MUTED });
  };
  bloque(M, AN / 2, `Avance acumulado ${r.año}`, r.anual.pct, `${r.anual.hechas} de ${r.anual.prog} actividades programadas registradas`, cN);
  page.drawLine({ start: { x: M + AN / 2, y: ini - 10 }, end: { x: M + AN / 2, y: ini - 78 }, thickness: 0.6, color: SUAVE });
  bloque(M + AN / 2, AN / 2, `Avance de ${MESES[r.mes]}`, r.mensual.pct, `${r.mensual.hechas} de ${r.mensual.prog} actividades del mes`, colorNivel(nivelDe(r.mensual.pct)));
  y = ini - 82;
  // Mensaje según el avance
  const mensaje = nivel === 'excelente'
    ? '¡Excelente trabajo! El colegio tiene al día el 100 % de su cronograma de mantenimiento. Felicidades a todo el equipo; sigan así.'
    : nivel === 'bien'
      ? 'Van por buen camino. No olviden los mantenimientos pendientes que se detallan en este reporte para llegar al 100 %.'
      : 'El avance se encuentra por debajo de lo esperado. Les pedimos atender los mantenimientos pendientes y registrarlos en el Sistema RCMA conforme se realicen.';
  const lm = envolver(mensaje, B, 9, AN - 60 - 90);
  const hm = 14 + lm.length * 12;
  rr(page, M + 12, y - hm, AN - 24, hm, 7, { color: nivel === 'excelente' ? rgb(0.92, 0.98, 0.94) : nivel === 'bien' ? rgb(1, 0.97, 0.9) : rgb(0.996, 0.93, 0.93) });
  page.drawRectangle({ x: M + 12, y: y - hm, width: 4, height: hm, color: cN });
  const et = etiquetaNivel(nivel).toUpperCase(), etw = B.widthOfTextAtSize(et, 7);
  rr(page, M + AN - 24 - etw - 18, y - hm / 2 - 7, etw + 14, 14, 7, { color: cN });
  page.drawText(et, { x: M + AN - 24 - etw - 11, y: y - hm / 2 - 2.5, size: 7, font: B, color: BLANCO });
  lm.forEach((l, k) => page.drawText(l, { x: M + 26, y: y - 16 - k * 12, size: 9, font: B, color: cN }));
  y -= hm + 10;
  cerrarTarjeta(ini);

  // Tabla genérica dentro de tarjeta
  const tabla = (titulo: string, cab: { t: string; x: number; der?: boolean }[], filas: { celdas: string[]; colores?: any[]; negritas?: boolean[] }[], vacio?: string) => {
    tituloTarjeta(titulo);
    let desde = y;
    const encabezado = () => {
      cab.forEach(c => { const w = B.widthOfTextAtSize(c.t.toUpperCase(), 6.8); page.drawText(c.t.toUpperCase(), { x: c.der ? c.x - w : c.x, y: y - 13, size: 6.8, font: B, color: MUTED }); });
      page.drawLine({ start: { x: M, y: y - 19 }, end: { x: M + AN, y: y - 19 }, thickness: 0.8, color: LINE });
      y -= 19;
    };
    encabezado();
    if (!filas.length && vacio) { page.drawText(vacio, { x: M + 12, y: y - 14, size: 9, font: B, color: VERDE }); y -= 22; }
    filas.forEach((f, k) => {
      if (y - 16 < 34) { cerrarTarjeta(desde); nuevaPagina(); tituloTarjeta(`${titulo} (continuación)`); desde = y; encabezado(); }
      if (k % 2 === 1) page.drawRectangle({ x: M + 0.5, y: y - 15, width: AN - 1, height: 15, color: rgb(0.973, 0.98, 0.988) });
      f.celdas.forEach((c, n) => {
        const font = f.negritas?.[n] ? B : R, w = font.widthOfTextAtSize(c, 8.5);
        page.drawText(c, { x: cab[n].der ? cab[n].x - w : cab[n].x, y: y - 11, size: 8.5, font, color: f.colores?.[n] ?? INK });
      });
      y -= 15;
    });
    y -= 4;
    cerrarTarjeta(desde);
  };

  tabla(`Desglose de ${MESES[r.mes]} por categoría`,
    [{ t: 'Categoría', x: M + 12 }, { t: 'Programadas', x: M + 360, der: true }, { t: 'Realizadas', x: M + 440, der: true }, { t: 'Avance', x: M + AN - 12, der: true }],
    r.categorias.map(c => { const p = pct(c.hechas, c.prog); return { celdas: [c.categoria, String(c.prog), String(c.hechas), `${p} %`], colores: [INK, INK, INK, colorNivel(nivelDe(p))], negritas: [false, false, false, true] }; }));

  tabla(`Mantenimientos pendientes de ${MESES[r.mes]}`,
    [{ t: 'Actividad', x: M + 12 }, { t: 'Categoría', x: M + 270 }, { t: 'Pendiente', x: M + AN - 12, der: true }],
    r.pendientes.map(p => ({ celdas: [p.actividad, p.categoria, `${p.veces} ${p.veces === 1 ? 'vez' : 'veces'}`], colores: [INK, MUTED, ROJO], negritas: [false, false, true] })),
    'Sin pendientes: todas las actividades del mes quedaron registradas.');

  // Reconocimiento con firma (solo al 100 %)
  if (nivel === 'excelente') {
    espacio(106);
    const firma = await pdf.embedPng(b64(FIRMA_B64));
    const bw = 250, bx = (W - bw) / 2, bh = 100;
    rr(page, bx, y - bh, bw, bh, 9, { borderColor: rgb(0.8, 0.84, 0.88), borderWidth: 1, borderDashArray: [3, 3] });
    const t = 'RECONOCIMIENTO';
    page.drawText(t, { x: W / 2 - B.widthOfTextAtSize(t, 8) / 2, y: y - 14, size: 8, font: B, color: VERDE });
    const fw = 120, fh = fw * firma.height / firma.width;
    page.drawImage(firma, { x: W / 2 - fw / 2, y: y - 66, width: fw, height: fh > 50 ? 50 : fh });
    page.drawLine({ start: { x: bx + 30, y: y - 70 }, end: { x: bx + bw - 30, y: y - 70 }, thickness: 0.8, color: rgb(0.58, 0.64, 0.72) });
    const n1 = 'Ing. Ricardo Joanathan Reyes Medina', n2 = 'Coordinador de Obras y Mantenimiento RCMA';
    page.drawText(n1, { x: W / 2 - B.widthOfTextAtSize(n1, 8.5) / 2, y: y - 81, size: 8.5, font: B, color: NAVY });
    page.drawText(n2, { x: W / 2 - R.widthOfTextAtSize(n2, 7.5) / 2, y: y - 92, size: 7.5, font: R, color: MUTED });
    y -= bh + 10;
  }

  for (const l of ([] as string[]).concat(envolver('El avance se calcula con las actividades del Cronograma de Mantenimiento registradas como realizadas en el Sistema RCMA. Cada actividad debe registrarse el día en que se realiza.', R, 7.5, AN - 60))) {
    if (y - 12 < 32) break; // si ya no cabe, se omite la nota (no abre una hoja solo para ella)
    page.drawText(l, { x: W / 2 - R.widthOfTextAtSize(l, 7.5) / 2, y: y - 8, size: 7.5, font: R, color: MUTED }); y -= 10;
  }

  pie();
  const paginas = pdf.getPages();
  paginas.forEach((p, k) => { const t = `${folio} · Sistema RCMA · Página ${k + 1} de ${paginas.length}`; p.drawText(t, { x: W - M - R.widthOfTextAtSize(t, 7.5), y: 10, size: 7.5, font: R, color: rgb(0.8, 0.84, 0.88) }); });
  return await pdf.save();
}

